import {jobs,stats,zones,monsters,items,quests,elementNames} from './data.js';
import {initial,derived,damage,hitChance,attackInterval,reward,advance,claimQuest,useItem,equip,socket,addItem,settleOffline,pathfind,clamp,elementMultiplier} from './engine.js';
import {World,blocked,portrait} from './world.js';
const $=id=>document.getElementById(id),key='vyriy-save-v1';let state;try{let raw=JSON.parse(localStorage.getItem(key));state=raw?.version===1&&raw.heroes?.length===6?raw:initial()}catch{state=initial()}if(state.bountyDay!==new Date().toISOString().slice(0,10)){state.bounty=0;state.bountyClaimed=false;state.bountyDay=new Date().toISOString().slice(0,10)}let afkReport=settleOffline(state);state.auto=false;const world=new World($('world'),state);let target=null,route=[],spawnTimer=0,uiTimer=0,last=0,paused=document.hidden,toastTimer,dialogPanel='',manual=false;let logs=state.log||[];
const nameItem=id=>items[id]?.name||(id.startsWith('card:')?'Карта: '+(monsters.find(m=>m.id===id.slice(5))?.name||'істота'):id);
function save(){try{state.lastSeen=Date.now();state.log=logs.slice(0,50);localStorage.setItem(key,JSON.stringify(state));$('save-state').textContent='збережено';}catch{$('save-state').textContent='недоступне';}}
function log(text){logs.unshift(text);logs=logs.slice(0,50);$('log-line').textContent=text;}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
function spawn(){world.entities=[];for(let i=0;i<14;i++)spawnOne(i);target=null;route=[];}
function spawnOne(i=0){let list=monsters.filter(m=>m.zone===state.zone),m=list[i%list.length];let x,y;for(let n=0;n<100;n++){x=3+Math.floor(Math.random()*20);y=3+Math.floor(Math.random()*20);if(!blocked(x,y))break;}world.entities.push({id:(crypto.randomUUID?.()||'mob-'+Math.random().toString(36).slice(2)),m,x,y,hp:m.hp,cd:1,dead:0});}
function xpPercent(h){return Math.min(100,h.xp/(h.base*50)*100)}
function renderUI(){let h=state.heroes[state.leader],d=derived(h),z=zones[state.zone],q=quests[state.quest];$('zeny').textContent='◉ '+state.zeny.toLocaleString('uk-UA')+' Z';$('zone-title').textContent=z.name;$('zone-sub').textContent=z.sub;$('region-level').textContent=`Рівні ${z.min}–${z.max}`;$('map-name').textContent=z.name;$('chapter').textContent=['I','II','III','IV','V'][state.quest];$('potion-count').textContent=state.inventory.potion||0;$('skill-name').textContent=jobs[h.job].skill;$('leader-summary').innerHTML=`<canvas class="portrait" data-portrait="${h.id}"></canvas><div><b>${h.name}</b><small>${jobs[h.job].name} · Рів. ${h.base}</small></div>`;$('party-list').innerHTML=state.heroes.map((a,i)=>{let dd=derived(a);return `<button class="hero-card ${i===state.leader?'selected':''}" data-hero="${i}" aria-label="Обрати ${a.name}"><canvas class="portrait" data-portrait="${i}"></canvas><div class="hero-info"><div class="hero-name"><b>${a.name} ${i===state.leader?'♧':''}</b><small>Рів. ${a.base}</small></div><div class="hp-track"><i style="width:${clamp(a.hp/dd.hp*100,0,100)}%"></i></div><div class="sp-track"><i style="width:${clamp(a.sp/dd.sp*100,0,100)}%"></i></div><div class="hero-class"><span>${jobs[a.job].name}</span><span>${Math.ceil(a.hp)} HP</span></div></div></button>`}).join('');document.querySelectorAll('[data-portrait]').forEach(c=>portrait(c,+c.dataset.portrait));$('quest-title').textContent=state.finished?'Оберіг знову сяє':q.title;$('quest-summary').textContent=state.finished?'Ви повернули світло Вирію. Полювання й розвиток загону тривають.':q.text.split('. ')[0]+'.';$('quest-objective').textContent=state.finished?'Історію завершено':'Здолати істот регіону';$('quest-count').textContent=`${Math.min(state.questKills,q.goal)} / ${q.goal}`;$('quest-progress').style.width=Math.min(100,state.questKills/q.goal*100)+'%';$('quest-action').innerHTML=state.finished?'Поговорити з Берегинею':state.questKills>=q.goal?'Отримати нагороду <span>✦</span>':'Прокласти маршрут <span>↗</span>';$('bounty-status').textContent=state.bountyClaimed?'Нагороду отримано':`Щоденне полювання · ${Math.min(state.bounty,20)} / 20`;$('auto').classList.toggle('on',state.auto);$('auto').innerHTML=`${state.auto?'Ⅱ':'▷'} Автобій <span>${state.auto?'УВІМК.':'ВИМК.'}</span>`;if(target&&target.hp>0){$('target-info').hidden=false;$('target-info').innerHTML=`${target.m.boss?'♛ ':''}${target.m.name} · ${target.m.level}<div class="hp-track"><i style="width:${target.hp/target.m.hp*100}%;background:#c98b74"></i></div>`;}else $('target-info').hidden=true;}
function chooseHero(id){state.leader=id;route=[];world.marker=null;renderUI();}
function nearest(){let h=state.heroes[state.leader];return world.entities.filter(e=>e.hp>0).sort((a,b)=>Math.hypot(a.x-h.x,a.y-h.y)-Math.hypot(b.x-h.x,b.y-h.y))[0]}
function moveTo(x,y){const h=state.heroes[state.leader];route=pathfind(h,{x,y},blocked);world.marker=route.length?{x,y}:null;if(!route.length)toast('Немає вільного шляху. Торкніться стежки.');}
function hunt(){target=nearest();if(!target)return;manual=true;moveTo(Math.round(target.x),Math.round(target.y));}
function kill(e){e.hp=0;e.dead=5;let drops=reward(state,e.m);world.effects.push({x:e.x,y:e.y,text:'+'+e.m.exp+' EXP',life:1.5,color:'#e9e6a9'});log(`${e.m.name} подолано · ${drops.map(nameItem).join(', ')} · +${e.m.zeny} Z`);if(drops.some(x=>x.startsWith('card:')))toast('Рідкісна знахідка — карта монстра!');target=null;if(!state.auto)manual=false;}
function heroAttack(h,e,mult=1,skill=false){if(h.hp<=0||e.hp<=0)return;let d=derived(h),magic=['mage','wizard','sage'].includes(h.job),crit=Math.random()<d.crit;if(!skill&&Math.random()>hitChance(d.hit,e.m.flee)){world.effects.push({x:e.x,y:e.y,text:'Промах',life:1});return;}let amount=damage(magic?d.matk:d.atk,magic?e.m.def*.8:e.m.def,mult,magic?elementMultiplier('fire',e.m.element):1,crit);e.hp-=amount;world.effects.push({x:e.x+(Math.random()-.5)*.3,y:e.y,text:(crit?'✦ ':'')+amount,life:1,color:skill?'#c7e3ff':undefined});if(e.hp<=0)kill(e);}
function skill(){let h=state.heroes[state.leader];if(h.hp<=0)return toast('Герой потребує відпочинку');if(h.skillCooldown>0)return toast(`Навичка відновиться за ${Math.ceil(h.skillCooldown)} с`);if(h.sp<10)return toast('Бракує SP. Випийте синє зілля.');if(['acolyte','priest'].includes(h.job)){state.heroes.forEach(a=>a.hp=Math.min(derived(a).hp,a.hp+derived(h).matk*2));toast('Загін огорнуло світло зцілення');}else{let e=target||nearest();if(!e)return;if(Math.hypot(e.x-h.x,e.y-h.y)>5){target=e;manual=true;moveTo(Math.round(e.x),Math.round(e.y));return toast('Підійдіть ближче до цілі');}heroAttack(h,e,2+h.skillLevel*.3,true);}h.sp-=10;h.skillCooldown=Math.max(2,6-h.stats.DEX*.01);log(`${h.name}: ${jobs[h.job].skill}`);renderUI();}
function camp(){state.auto=false;manual=false;target=null;state.heroes.forEach((h,i)=>{h.hp=derived(h).hp;h.sp=derived(h).sp;h.x=11+i%3;h.y=13+Math.floor(i/3)});route=[];world.marker=null;toast('Відпочинок біля вогнища · HP та SP відновлено');log('Загін відпочив у безпечному таборі.');save();renderUI();}
function tick(dt){let leader=state.heroes[state.leader];if(state.auto&&(!target||target.hp<=0)){target=nearest();if(target)route=pathfind(leader,{x:Math.round(target.x),y:Math.round(target.y)},blocked);}for(let h of state.heroes){h.cooldown=Math.max(0,h.cooldown-dt);h.skillCooldown=Math.max(0,h.skillCooldown-dt);h.moving=false;if(h.hp>0){h.hp=Math.min(derived(h).hp,h.hp+dt*(.25+h.stats.VIT*.02));h.sp=Math.min(derived(h).sp,h.sp+dt*(.3+h.stats.INT*.02));}}
if(route.length&&leader.hp>0){let [x,y]=route[0],dist=Math.hypot(x-leader.x,y-leader.y);if(dist<.12){leader.x=x;leader.y=y;route.shift();if(!route.length)world.marker=null;}else{let step=Math.min(dist,dt*3.2);leader.x+=(x-leader.x)/dist*step;leader.y+=(y-leader.y)/dist*step;leader.moving=true;}}
for(let h of state.heroes){if(h===leader||h.hp<=0)continue;let i=h.id,tx=leader.x+(i%3-1)*.7,ty=leader.y+(Math.floor(i/3)+1)*.6;if(blocked(Math.round(tx),Math.round(ty))){tx=leader.x;ty=leader.y;}let dist=Math.hypot(tx-h.x,ty-h.y);if(dist>.45){let nx=h.x+(tx-h.x)*Math.min(1,dt*3),ny=h.y+(ty-h.y)*Math.min(1,dt*3);if(!blocked(Math.round(nx),Math.round(ny))){h.x=nx;h.y=ny;h.moving=true;}else{let path=pathfind(h,{x:Math.round(leader.x),y:Math.round(leader.y)},blocked);if(path.length){let [px,py]=path[0];h.x+=(px-h.x)*Math.min(1,dt*3);h.y+=(py-h.y)*Math.min(1,dt*3);}}}}
if((state.auto||manual)&&target&&target.hp>0){let e=target;for(let h of state.heroes){let range=['archer','hunter','bard','mage','wizard','sage'].includes(h.job)?5:2.4;if(Math.hypot(e.x-h.x,e.y-h.y)<=range&&h.cooldown<=0&&h.hp>0){heroAttack(h,e,state.tactic==='aggressive'?1.2:1);h.cooldown=attackInterval(derived(h).aspd)*(state.tactic==='defensive'?1.15:1);if(state.auto&&h.sp>=10&&h.skillCooldown===0&&h.hp>0){if(['acolyte','priest'].includes(h.job)){let weak=state.heroes.filter(a=>a.hp>0).sort((a,b)=>a.hp/derived(a).hp-b.hp/derived(b).hp)[0];if(weak)weak.hp=Math.min(derived(weak).hp,weak.hp+derived(h).matk*2);}else if(e.hp>0)heroAttack(h,e,1.8+h.skillLevel*.2,true);h.sp-=10;h.skillCooldown=7;}}}if(e.hp>0&&Math.hypot(e.x-leader.x,e.y-leader.y)<3){e.cd-=dt;if(e.cd<=0){let victim=state.heroes.filter(h=>h.hp>0).sort((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y))[0];if(victim){let d=derived(victim);if(Math.random()<hitChance(65+e.m.level*2,d.flee)&&Math.random()>d.dodge){let amount=damage(e.m.atk,d.def,state.tactic==='defensive'?.7:1);victim.hp=Math.max(0,victim.hp-amount);world.effects.push({x:victim.x,y:victim.y,text:'−'+amount,life:1,color:'#ffb7a5'});if(e.m.boss)state.heroes.filter(h=>h.hp>0&&h!==victim).forEach(h=>h.hp=Math.max(0,h.hp-Math.ceil(amount*.25)));}}e.cd=1.6;}}}
if(!state.heroes.some(h=>h.hp>0)){camp();toast('Загін відступив до вогнища. Лут збережено.');}else if(leader.hp<=0)chooseHero(state.heroes.findIndex(h=>h.hp>0));for(let e of world.entities){if(e.hp<=0)e.dead-=dt;}let dead=world.entities.filter(e=>e.hp<=0&&e.dead<=0);world.entities=world.entities.filter(e=>!(e.hp<=0&&e.dead<=0));dead.forEach(()=>spawnOne(Math.floor(Math.random()*8)));}
function openPanel(name){dialogPanel=name;let title='',html='',h=state.heroes[state.leader],d=derived(h);switch(name){case'world':title='Стежки Вирію';html=`<p class="muted">Виконуйте сюжетні завдання, щоб відкривати нові регіони.</p><div class="panel-grid">${zones.map((z,i)=>`<div class="panel-card"><p class="eyebrow">РЕГІОН ${i+1} · РІВ. ${z.min}–${z.max}</p><h3>${z.name}</h3><p>${z.sub}</p><button data-zone="${i}" ${state.quest<i?'disabled':''}>${state.quest<i?'🔒 Зачинено':state.zone===i?'Ви тут':'Подорожувати →'}</button></div>`).join('')}</div>`;break;
case'party':title='Загін · '+h.name;html=`<div class="panel-grid">${state.heroes.map(a=>`<div class="panel-card"><h3>${a.name}</h3><span class="tag">${jobs[a.job].name} · Base ${a.base} / Job ${a.jobLevel}</span><p>HP ${Math.ceil(a.hp)} / ${derived(a).hp} · SP ${Math.floor(a.sp)}<br>Досвід: ${a.xp} / ${a.base*50}<br>Зброя: ${a.gear.weapon?nameItem(a.gear.weapon):'немає'}<br>Броня: ${a.gear.armor?nameItem(a.gear.armor):'немає'}</p><button data-select="${a.id}">Обрати ${state.leader===a.id?'✓':''}</button></div>`).join('')}</div><h3>Характеристики: ${h.name}</h3><p class="muted">Вільні очки: ${h.statPoints} · підвищення коштує 1 очко.</p>${stats.map(k=>`<div class="stat-row"><span>${k}</span><b>${h.stats[k]}</b><button data-stat="${k}" ${h.statPoints<1?'disabled':''}>+</button></div>`).join('')}<p class="stats-summary">ATK ${d.atk} · MATK ${d.matk} · DEF ${d.def.toFixed(1)} · HIT ${d.hit} · FLEE ${d.flee.toFixed(1)}<br>ASPD ${d.aspd.toFixed(1)} · CRIT ${(d.crit*100).toFixed(1)}% · вага ${d.capacity}</p>`;break;
case'inventory':title='Торба мандрівника';let weight=Object.entries(state.inventory).reduce((v,[k,n])=>v+(items[k]?.weight||1)*n,0);html=`<p class="muted">Обрано: ${h.name} · вага ${weight} / ${state.heroes.reduce((v,a)=>v+derived(a).capacity,0)} · ${state.zeny} Z</p><div class="panel-grid">${Object.entries(state.inventory).filter(([k,n])=>n>0).map(([id,n])=>{let item=items[id];return`<div class="panel-card"><span class="item-icon">${item?.icon||'▧'}</span> <span class="tag">×${n}</span><h3>${nameItem(id)}</h3><p>${item?.desc||(id.startsWith('card:')?'Карта монстра. У гнізді: +2 ATK та +2 MATK. Один слот — одна карта.':'Матеріал для продажу торговцеві.')}</p>${item?.type==='consumable'?`<button data-use="${id}">Використати</button>`:['weapon','armor'].includes(item?.type)?`<button data-equip="${id}">Одягнути</button>`:id.startsWith('card:')?`<button data-socket="${id}" data-slot="weapon">У зброю</button><button data-socket="${id}" data-slot="armor">У броню</button>`:`<button class="secondary" data-sell="${id}">Продати · ${item?.price||1} Z</button>`}</div>`}).join('')||'<p class="empty">Торба порожня. Час вирушати на полювання.</p>'}</div>`;break;
case'jobs':title='Дерево професій · '+h.name;let j=jobs[h.job],required=h.job==='novice'?10:40;html=`<div class="notice">${j.icon} ${j.name} · Job ${h.jobLevel} / 50 · Очки навичок: ${h.skillPoints}<br>Базовий і професійний рівні розвиваються окремо.</div><h3>${j.skill} · ранг ${h.skillLevel} / 10</h3><p>Вартість: 10 SP. Активний удар або зцілення; кожен ранг посилює навичку.</p><button class="btn" id="upgrade-skill" ${h.skillPoints<1||h.skillLevel>=10?'disabled':''}>Покращити · 1 очко</button><h3>Наступний крок</h3><p class="muted">${j.branches?`Потрібно Job ${required}. Після переходу професійний рівень починається з 1; характеристики зберігаються.`:'Вершина професійного шляху. Продовжуйте розвивати базовий рівень і навичку.'}</p><div class="panel-grid">${(j.branches||[]).map(id=>`<div class="panel-card"><span class="item-icon">${jobs[id].icon}</span><h3>${jobs[id].name}</h3><p>${jobs[id].skill}</p><button data-job="${id}" ${h.jobLevel<required?'disabled':''}>Обрати професію</button></div>`).join('')}</div><h3>Усі шляхи</h3>${jobs.novice.branches.map(id=>`<p class="stats-summary">${jobs[id].icon} ${jobs[id].name} → ${jobs[id].branches.map(b=>jobs[b].name).join(' / ')}</p>`).join('')}`;break;
case'bestiary':title='Бестіарій · 40 істот';html=`<div class="panel-grid">${monsters.map(m=>`<div class="panel-card"><p class="eyebrow">${zones[m.zone].name} · ${m.boss?'MVP БОС':'ІСТОТА'}</p><h3>${m.name}</h3><span class="tag">Рів. ${m.level} · ${elementNames[m.element]}</span><p>HP ${m.hp} · ATK ${m.atk} · DEF ${m.def}<br>${m.behavior}<br>Лут: ${nameItem(m.drop)}; карта — 2% + LUK.<br>${state.discovered.includes(m.id)?'✓ Подолано':'Ще не подолано'}</p></div>`).join('')}</div>`;break;
case'shop':title='Крамниця Данила';html=`<p class="notice">Тут можна купувати спорядження й продавати лут. P2P-ринок потребує серверної версії; цей магазин працює локально.</p><div class="panel-grid">${['potion','ether','sword','staff','armor'].map(id=>`<div class="panel-card"><span class="item-icon">${items[id].icon}</span><h3>${items[id].name}</h3><p>${items[id].desc}</p><button data-buy="${id}" ${state.zeny<items[id].price?'disabled':''}>Купити · ${Math.ceil(items[id].price*(h.job==='merchant'?.9:1))} Z</button></div>`).join('')}</div>`;break;
case'journal':title='Журнал подорожі';html=logs.map(t=>`<p>✧ ${t}</p>`).join('')||'<p>Ваша історія щойно почалась.</p>';break;
case'tactics':title='Тактика загону';html=`<p class="muted">Під час автобою герої атакують і витрачають SP на навички. Послушники та жерці лікують союзників.</p><div class="panel-grid">${[['balanced','Рівновага','Звичайні атаки та захист.'],['aggressive','Натиск','На 20% більше шкоди.'],['defensive','Оборона','На 30% менше вхідної шкоди, атаки повільніші на 15%.']].map(([id,n,t])=>`<div class="panel-card"><h3>${n}</h3><p>${t}</p><button data-tactic="${id}">${state.tactic===id?'Обрано ✓':'Застосувати'}</button></div>`).join('')}</div>`;break;
case'afk':title='Офлайн-полювання';html=`<p class="notice">Локальна симуляція: до 4 годин, одне полювання за хвилину, 35% досвіду. Лише звичайні істоти не вище найслабшого героя +2 рівні. Завдання й карти офлайн не зараховуються.</p><p>Зараз: ${state.afkZone===null?'вимкнено':zones[state.afkZone].name}. Винагорода розраховується після повернення; вкладку можна закрити.</p><button class="btn" id="enable-afk">Полювати: ${zones[state.zone].name}</button><button class="btn secondary" id="disable-afk">Вимкнути</button><p class="muted">У мережевій версії час і винагороди перевірятиме сервер.</p>`;break;
case'settings':title='Збереження та керування';html=`<p>Дотик до землі — рух; до істоти — вибір і атака. Клавіші 1–4 — дії, Escape — закрити меню. Прогрес автоматично зберігається у цьому браузері.</p><button class="btn" id="export-save">Експортувати збереження</button><label class="btn secondary">Імпортувати<input id="import-save" type="file" accept="application/json" hidden></label><p class="notice">Соло-прототип v0.1: локальна економіка, процедурні піксельні спрайти й портрети. Повноцінні аніме-портрети та серверний мультиплеєр — наступні етапи.</p>`;break;
case'help':title='Світло починається з тебе';html=`<div class="dialogue"><canvas id="npc-portrait"></canvas><div><p>«Я Орися, берегиня цих земель. Оберіг розбитий, але шість іскор ще можуть повернути світло. Почніть з росинок на Вербових луках».</p><small class="muted">Берегиня Орися · Розділ I</small></div></div><p>Торкніться істоти або увімкніть <b>Автобій</b>. Перемикайте лідера через картки загону. Завдання відкривають нові регіони; підвищуйте характеристики й обирайте професії на Job 10.</p><p>Початкові 12 зіль — у торбі. Вогнище відновлює загін без штрафу. Заглядaйте до крамниці: спорядження значно підсилює героїв.</p><button class="btn" id="start-adventure">Вирушити у пригоду →</button>`;break;
case'quest':title=state.finished?'Світло повернулося':quests[state.quest].title;let q=quests[state.quest];html=`<p class="eyebrow">${q.npc}</p><p>${state.finished?'Шість іскор знову стали одним світлом. Вирій пам’ятатиме ваші імена. Дякую, мандрівники.':q.text}</p><p>Здолати ${q.goal} істот: ${zones[q.zone].name}. Нагорода: ${q.reward} Z та ${q.reward} EXP кожному.</p><button class="btn" id="track-quest">${state.finished?'Продовжити мандрівку':state.questKills>=q.goal?'Завершити завдання':'До завдання →'}</button>`;break;
} $('modal-title').textContent=title;$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal();if($('npc-portrait'))portrait($('npc-portrait'),3,true);}
function close(){$('modal').close();dialogPanel='';}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let ds=b.dataset;if(ds.panel)openPanel(ds.panel);if(ds.hero!==undefined)chooseHero(+ds.hero);if(ds.select!==undefined){chooseHero(+ds.select);openPanel('party')}if(ds.stat){let h=state.heroes[state.leader];if(h.statPoints>0){h.stats[ds.stat]++;h.statPoints--;openPanel('party');save();}}if(ds.zone!==undefined&&+ds.zone<=state.quest){state.zone=+ds.zone;state.auto=false;state.heroes.forEach((h,i)=>{h.x=12+i%3;h.y=13+Math.floor(i/3)});spawn();close();renderUI();save();}if(ds.use){useItem(state,ds.use);openPanel('inventory')}if(ds.equip){if(!equip(state,ds.equip))toast('Спочатку використайте іншого героя: слот із картою заблоковано');openPanel('inventory')}if(ds.socket){if(!socket(state,ds.socket,ds.slot))toast('Потрібне спорядження з вільним гніздом');else toast('Карту встановлено');openPanel('inventory')}if(ds.sell&&state.inventory[ds.sell]>0){state.inventory[ds.sell]--;state.zeny+=items[ds.sell]?.price||1;openPanel('inventory')}if(ds.buy){let price=Math.ceil(items[ds.buy].price*(state.heroes[state.leader].job==='merchant'?.9:1));if(state.zeny>=price&&addItem(state,ds.buy)){state.zeny-=price;openPanel('shop');toast('Покупку додано в торбу');}else toast('Бракує Zeny або місця');}if(ds.job){if(advance(state.heroes[state.leader],ds.job)){log(`${state.heroes[state.leader].name} обирає шлях: ${jobs[ds.job].name}`);openPanel('jobs');save();}}if(ds.tactic){state.tactic=ds.tactic;openPanel('tactics');save();}renderUI();});
$('world').addEventListener('pointerdown',e=>{let r=$('world').getBoundingClientRect(),p=world.unproject(e.clientX-r.left,e.clientY-r.top);let hit=world.entities.filter(a=>a.hp>0).map(a=>({a,p:world.project(a.x,a.y)})).find(a=>Math.hypot(a.p.x-(e.clientX-r.left),a.p.y-15-(e.clientY-r.top))<(a.a.m.boss?35:25));if(hit){target=hit.a;manual=true;moveTo(Math.round(target.x),Math.round(target.y));toast(`${target.m.name} · рів. ${target.m.level}`);}else{state.auto=false;manual=false;target=null;moveTo(p.x,p.y);}renderUI();});
$('close').onclick=close;$('modal').addEventListener('close',()=>dialogPanel='');$('modal').addEventListener('click',e=>{if(e.target===$('modal')){let r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
$('attack').onclick=hunt;$('skill').onclick=skill;$('potion').onclick=()=>{toast(useItem(state,'potion')?'HP відновлено':'Червоні зілля закінчилися');renderUI();save()};$('camp').onclick=camp;$('auto').onclick=()=>{state.auto=!state.auto;manual=false;if(!state.auto){route=[];world.marker=null;target=null;}renderUI()};$('map-button').onclick=()=>openPanel('world');$('help').onclick=()=>openPanel('help');$('tactic').onclick=()=>openPanel('tactics');$('afk').onclick=()=>openPanel('afk');$('quest-action').onclick=()=>openPanel('quest');$('bounty').onclick=()=>{if(state.bounty>=20&&!state.bountyClaimed){state.bountyClaimed=true;state.zeny+=200;addItem(state,'potion',3);toast('Доручення виконано: +200 Z та 3 зілля');save();renderUI()}else toast(state.bountyClaimed?'Сьогодні нагороду вже отримано':'Здолайте 20 істот для нагороди')};
$('modal-content').addEventListener('click',e=>{let id=e.target.closest('[id]')?.id;if(id==='start-adventure')close();if(id==='upgrade-skill'){let h=state.heroes[state.leader];if(h.skillPoints>0&&h.skillLevel<10){h.skillPoints--;h.skillLevel++;openPanel('jobs');save()}}if(id==='track-quest'){if(state.finished){close();return}if(state.questKills>=quests[state.quest].goal){let n=quests[state.quest].reward;claimQuest(state);log(`Завдання виконано! +${n} Z. Новий шлях відкрито.`);save();renderUI();close();toast('Нагороду отримано. Перевірте карту світу.')}else{state.zone=quests[state.quest].zone;spawn();state.auto=true;close();renderUI()}}if(id==='enable-afk'){state.afkZone=state.zone;save();openPanel('afk')}if(id==='disable-afk'){state.afkZone=null;save();openPanel('afk')}if(id==='export-save'){save();let url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='vyriy-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}});
$('modal-content').addEventListener('change',async e=>{if(e.target.id!=='import-save')return;try{let raw=JSON.parse(await e.target.files[0].text());validateSave(raw);state=raw;state.auto=false;world.state=state;save();spawn();renderUI();close();toast('Збереження відновлено')}catch{toast('Невірний файл збереження')}});
function validateSave(s){if(s.version!==1||!Array.isArray(s.heroes)||s.heroes.length!==6||!Number.isInteger(s.zone)||s.zone<0||s.zone>4||!Number.isInteger(s.quest)||s.quest<0||s.quest>4||!Number.isInteger(s.leader)||s.leader<0||s.leader>5||!Number.isFinite(s.zeny)||s.zeny<0||!s.inventory||typeof s.inventory!=='object')throw Error();for(let h of s.heroes){if(!jobs[h.job]||typeof h.name!=='string'||!/^\p{L}[\p{L} ’'-]{0,30}$/u.test(h.name)||!h.gear||!h.cards||!stats.every(k=>Number.isFinite(h.stats?.[k])&&h.stats[k]>=0&&h.stats[k]<=999)||!['base','jobLevel','hp','sp','xp','jxp','statPoints','skillPoints','skillLevel','x','y','cooldown','skillCooldown'].every(k=>Number.isFinite(h[k])&&h[k]>=0))throw Error();}for(let [id,n]of Object.entries(s.inventory)){if((!items[id]&&!monsters.some(m=>'card:'+m.id===id))||!Number.isInteger(n)||n<0)throw Error();}s.log=[];}
document.addEventListener('keydown',e=>{if($('modal').open||e.target.matches('input'))return;let action={'1':hunt,'2':skill,'3':()=>$('potion').click(),'4':camp};action[e.key]?.()});
document.addEventListener('visibilitychange',()=>{paused=document.hidden;if(paused)save();else{let report=settleOffline(state);if(report)toast(`Повернення: +${report.zeny} Z, +${report.xp} EXP`);last=0;renderUI()}});window.addEventListener('pagehide',save);setInterval(()=>{if(!paused)save()},10000);
function frame(t){let dt=last?Math.min((t-last)/1000,.06):0;last=t;if(!paused){if(!$('modal').open)tick(dt);world.render(dt);uiTimer+=dt;if(uiTimer>.4){renderUI();uiTimer=0;}}requestAnimationFrame(frame)}spawn();renderUI();requestAnimationFrame(frame);if(afkReport){openPanel('afk');toast(`Офлайн: +${afkReport.zeny} Z, +${afkReport.xp} EXP`)}else if(!localStorage.getItem(key))setTimeout(()=>openPanel('help'),500);
